import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const g=JSON.parse('{"title":"Metal Mashup","description":"","frontmatter":{},"headers":[],"relativePath":"demos/METAL_MASHUP.md","filePath":"demos/METAL_MASHUP.md"}'),l={name:"demos/METAL_MASHUP.md"};function r(n,e,i,h,m,d){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="metal-mashup" tabindex="-1">Metal Mashup <a class="header-anchor" href="#metal-mashup" aria-label="Permalink to &quot;Metal Mashup&quot;">​</a></h1><p>The mashups that set another work&#39;s notes on a metal band. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#got_some_strings">The Ride of the Valkyries as Thrash Metal</a>: <code>got_some_strings.yml</code></li><li><a href="#not_so_simple">Simple Gifts as Progressive Metal</a>: <code>not_so_simple.yml</code></li><li><a href="#slow_seventh">The Allegretto of the Seventh Symphony as Doom Metal</a>: <code>slow_seventh.yml</code></li><li><a href="#trooping_trolls">Grieg as Galloping Heavy Metal</a>: <code>trooping_trolls.yml</code></li></ul><p><a id="got_some_strings"></a></p><h2 id="the-ride-of-the-valkyries-as-thrash-metal-got-some-strings-yml" tabindex="-1">The Ride of the Valkyries as Thrash Metal: <code>got_some_strings.yml</code> <a class="header-anchor" href="#the-ride-of-the-valkyries-as-thrash-metal-got-some-strings-yml" aria-label="Permalink to &quot;The Ride of the Valkyries as Thrash Metal: `got_some_strings.yml`&quot;">​</a></h2><p>Got some strings: the Ride of the Valkyries as eighties thrash metal, after Master of Puppets (Metallica). The horn theme of the Ride of the Valkyries (Richard Wagner, 1856) is public domain and is played as written, in its key and its nine-eight time, from Claude&#39;s knowledge of the score; the chugging riffs, the chromatic licks, the solos and the drums are new, and nothing of the reference&#39;s own riffs is quoted.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/metal/got_some_strings.yml" target="_blank" rel="noreferrer"><code>examples/mashups/metal/got_some_strings.yml</code></a> · B minor · 172 BPM · 2:56 · 15 scenes · 12 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="not_so_simple"></a></p><h2 id="simple-gifts-as-progressive-metal-not-so-simple-yml" tabindex="-1">Simple Gifts as Progressive Metal: <code>not_so_simple.yml</code> <a class="header-anchor" href="#simple-gifts-as-progressive-metal-not-so-simple-yml" aria-label="Permalink to &quot;Simple Gifts as Progressive Metal: `not_so_simple.yml`&quot;">​</a></h2><p>Not so simple: the Shaker song Simple Gifts (Joseph Brackett, 1848) played as progressive metal of the nineties, in the manner of Dream Theater. Both strains of the tune are Brackett&#39;s, note for note, in several keys and speeds; the riffs, the runs, the solos and the drums are new. One clean guitar plays the tune plainly; a riff in threes turns it heavy; the second strain goes by twice as fast with guitar and keyboard in unison; the two trade fast solos over the tune&#39;s chords; the tune comes back a third higher in harmony over groups of seven, then grand and slow; runs fly over the tune in the bass; and one clean guitar ends it as it began.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/metal/not_so_simple.yml" target="_blank" rel="noreferrer"><code>examples/mashups/metal/not_so_simple.yml</code></a> · D major · 96 BPM · 2:56 · 12 scenes · 15 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">tempo changes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="slow_seventh"></a></p><h2 id="the-allegretto-of-the-seventh-symphony-as-doom-metal-slow-seventh-yml" tabindex="-1">The Allegretto of the Seventh Symphony as Doom Metal: <code>slow_seventh.yml</code> <a class="header-anchor" href="#the-allegretto-of-the-seventh-symphony-as-doom-metal-slow-seventh-yml" aria-label="Permalink to &quot;The Allegretto of the Seventh Symphony as Doom Metal: `slow_seventh.yml`&quot;">​</a></h2><p>Slow seventh: the Allegretto of the Seventh Symphony as doom metal. The violas&#39; theme and the melody they play against it at its second hearing, from the Allegretto of the Symphony No. 7 (Ludwig van Beethoven, 1812), are public domain and are played as written, read from the Mutopia Project&#39;s edition; the slow power chords, the bent licks with their flat fifths, the solos and the drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/metal/slow_seventh.yml" target="_blank" rel="noreferrer"><code>examples/mashups/metal/slow_seventh.yml</code></a> · A minor · 60 BPM · 3:04 · 7 scenes · 12 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="trooping_trolls"></a></p><h2 id="grieg-as-galloping-heavy-metal-trooping-trolls-yml" tabindex="-1">Grieg as Galloping Heavy Metal: <code>trooping_trolls.yml</code> <a class="header-anchor" href="#grieg-as-galloping-heavy-metal-trooping-trolls-yml" aria-label="Permalink to &quot;Grieg as Galloping Heavy Metal: `trooping_trolls.yml`&quot;">​</a></h2><p>Trooping trolls: Grieg&#39;s In the Hall of the Mountain King played as galloping heavy metal of the early eighties, in the manner of The Trooper (Iron Maiden). The theme, its second phrase, its bass lines and its ending are Grieg&#39;s, note for note, moved by octaves to suit the guitars; the gallop, the twin-guitar line, the answering licks, the solos and the drums are new. The theme creeps in on the bass alone, as Grieg has it; a guitar joins, the two lead guitars answer in the gaps; the band breaks into a gallop with a twin-guitar line; the guitars pass the theme between them and play it in thirds; they trade solos while the theme runs underneath; the last cycle strides over Grieg&#39;s falling bass, and his crashes end it with drum fills in the silences.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/metal/trooping_trolls.yml" target="_blank" rel="noreferrer"><code>examples/mashups/metal/trooping_trolls.yml</code></a> · B minor · 138 BPM · 2:54 · 18 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">tempo changes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',23)])])}const c=t(l,[["render",r]]);export{g as __pageData,c as default};
